/** Picture-book cloud (cream puffs with a soft brown outline). */
const Cloud = ({x, y, s = 1, opacity = 1}: {x: number; y: number; s?: number; opacity?: number}) => opacity <= 0 ? null :
  <g transform={`translate(${x} ${y}) scale(${s})`} opacity={opacity}>
    <path d="M -130 30 C -150 30 -160 0 -132 -8 C -140 -40 -96 -56 -72 -36 C -64 -76 -4 -84 12 -46 C 30 -74 84 -66 88 -30 C 120 -40 150 -10 132 18 C 150 30 140 40 120 40 L -120 40 Z"
      fill="#fff8ec" stroke="#d9b58a" strokeWidth={3} strokeLinejoin="round" />
    <path d="M -100 22 C -60 30 20 30 100 22" stroke="#f1dcc0" strokeWidth={6} fill="none" strokeLinecap="round" />
  </g>;

/** Heat shimmer drawn as vector bands: translucent wavy ribbons drifting up and wobbling over the hot horizon.
 * (Copies of the plate, as strips or as a masked layer, looked more like real refraction but rendered differently
 * run to run on the GPU path and failed the delivery check with CODE_NONDETERMINISTIC.) */
function HeatHaze({t, y0, y1, amount = 1, n = 9}: {asset?: any; frame?: number; t: number; y0: number; y1: number; amp?: number; amount?: number; n?: number}) {
  if (amount <= 0) return null;
  const band = (y1 - y0) / n;
  return <Svg><g fill="none" strokeLinecap="round">{Array.from({length: n}, (_, i) => {
    const k = ((t * .22 + i / n) % 1), y = y1 - k * (y1 - y0), op = Math.sin(Math.PI * k) * .22 * amount;
    const pts = Array.from({length: 25}, (_, j) => {const x = j * 80; return `${x},${(y + Math.sin(j * .9 + t * 4.2 + i * 1.7) * band * .18).toFixed(1)}`;});
    return <polyline key={i} points={pts.join(' ')} stroke="#fff3dc" strokeWidth={band * .32} opacity={op} />;
  })}</g></Svg>;
}
/** Rising heat lines (wavy, translucent). */
function HeatLines({t, x0, x1, y, n = 9, amount = 1, seed = 4}: {t: number; x0: number; x1: number; y: number; n?: number; amount?: number; seed?: number}) {
  if (amount <= 0) return null;
  const r = seeded(seed), items = Array.from({length: n}, () => ({x: x0 + r() * (x1 - x0), ph: r(), h: 90 + r() * 90}));
  return <g fill="none" strokeLinecap="round">{items.map((it, i) => {
    const k = (t * .55 + it.ph) % 1, yy = y - k * 160, op = Math.sin(Math.PI * k) * .55 * amount;
    const path = `M ${it.x} ${yy} q 12 ${-it.h / 4} 0 ${-it.h / 2} q -12 ${-it.h / 4} 0 ${-it.h / 2}`;
    return <path key={i} d={path} stroke="#fff3d6" strokeWidth={5} opacity={op} />;
  })}</g>;
}
/** Rain streaks (canvas, frame-deterministic). */
function Rain({frame, amount = 1, angle = .16, seed = 3, opacity = 1}: {frame: number; amount?: number; angle?: number; seed?: number; opacity?: number}) {
  const r = seeded(seed), drops = Array.from({length: 420}, () => ({x: r() * W * 1.3, y: r() * H, l: 26 + r() * 50, v: 1300 + r() * 1100, z: r()}));
  const ref = useCanvas(frame, (c, f) => {
    const t = f / 30;
    c.lineCap = 'round';
    drops.forEach((d, i) => {
      if (i / drops.length > amount) return;
      const y = (d.y + d.v * t) % (H + 120) - 60, x = (d.x - y * angle) % (W * 1.3) - W * .15;
      c.strokeStyle = `rgba(225,240,255,${.25 + .45 * d.z})`; c.lineWidth = 1 + 2 * d.z;
      c.beginPath(); c.moveTo(x, y); c.lineTo(x - d.l * angle, y + d.l); c.stroke();
    });
  });
  if (opacity <= 0) return null;
  return <canvas ref={ref} width={W} height={H} style={{position: 'absolute', inset: 0, width: '100%', height: '100%', opacity}} />;
}
/** Night stars and a friendly moon. */
function NightSky({t, amount = 1, moonX = 1560, moonY = 170}: {t: number; amount?: number; moonX?: number; moonY?: number}) {
  if (amount <= 0) return null;
  const r = seeded(91), stars = Array.from({length: 60}, () => ({x: r() * W, y: r() * 420, s: r()}));
  return <div style={{position: 'absolute', inset: 0, pointerEvents: 'none'}}>
    <div style={{position: 'absolute', inset: 0, opacity: amount, background: 'linear-gradient(180deg, rgba(20,34,90,.88), rgba(30,40,90,.62) 55%, rgba(20,24,60,.55))', mixBlendMode: 'multiply'}} />
    <Svg style={{opacity: amount}}>{stars.map((s, i) => <Twinkle key={i} x={s.x} y={s.y} s={.18 + .3 * s.s} opacity={.35 + .6 * Math.abs(Math.sin(t * 2 + i))} />)}
      <circle cx={moonX} cy={moonY} r={120} fill="#fdf3c8" opacity={.18} /><circle cx={moonX} cy={moonY} r={90} fill="#fdf3c8" opacity={.25} />
      <circle cx={moonX} cy={moonY} r={70} fill="#fdf3c8" />
      <circle cx={moonX + 30} cy={moonY - 18} r={60} fill="rgba(30,40,90,.0)" /></Svg>
  </div>;
}
/** Warm sky tint (multiply + screen layers), amount 0..1. */
function Heat({amount = 1, t = 0}: {amount?: number; t?: number}) {
  if (amount <= 0) return null;
  const pulse = 1 + .05 * Math.sin(t * 3);
  return <>
    <div style={{position: 'absolute', inset: 0, opacity: amount, background: 'linear-gradient(180deg, rgba(255,120,40,.55), rgba(255,170,60,.25) 60%, rgba(255,140,40,.2))', mixBlendMode: 'multiply'}} />
    <div style={{position: 'absolute', inset: 0, opacity: amount * .5 * pulse, background: 'radial-gradient(ellipse at 50% 10%, rgba(255,236,170,.75), rgba(255,200,90,0) 65%)', mixBlendMode: 'screen'}} />
  </>;
}
/** Soft vignette. */
const Finish = ({vignette = .38}: {vignette?: number}) =>
  <div style={{position: 'absolute', inset: 0, background: `radial-gradient(ellipse at center, rgba(40,15,0,0) 52%, rgba(40,15,0,${vignette}) 100%)`}} />;
/** Decaying camera shake. */
const shake = (t: number, at: number, power = 14, len = .45) => {
  const d = t - at;
  if (d < 0 || d > len) return '';
  const k = (1 - d / len) * power;
  return `translate(${(Math.sin(d * 90) * k).toFixed(2)}px, ${(Math.cos(d * 70) * k * .7).toFixed(2)}px)`;
};
const fadeEdges = (t: number, dur: number, inS = .15, outS = .15) => Math.min(sm(t / inS), sm((dur - t) / outS));
/** Small caption-like note in the host text font. */
const Note = ({children, x, y, size = 30, color = 'rgba(255,244,224,.92)', opacity = 1, align = 'left', fonts}: any) =>
  !children || opacity <= 0 ? null : <div style={{position: 'absolute', left: align === 'center' ? 0 : x, right: align === 'center' ? 0 : undefined, top: y,
    textAlign: align === 'center' ? 'center' : 'left', fontFamily: fonts?.text, fontSize: size, letterSpacing: typeof children === 'string' && isLatin(children) ? 1 : 4,
    color, opacity, textShadow: '0 2px 10px rgba(60,20,0,.85)', whiteSpace: 'nowrap', fontWeight: 600}}>{children}</div>;

// Hou Yi, six modes. hero: name brushed in, glints run along the red bow and the white arrows on the cue words.
// call: he calls up, sound rings fly out, the crows keep playing. draw: the frame tightens as the bow is drawn; a moon ring.
// first: arrow arc on the whoosh cue, flash + feather burst on the hit cue, feathers drift into the sea, counter 10 -> 9.
// volley: one hit per counted word, ever faster, counter follows. last: zoom on the last crow, villagers plead, Hou Yi lowers the bow.
export const meta = {
  params: {
    mode: {label: '模式', type: 'select', default: 'hero', options: [{value: 'hero', label: '神箭手'}, {value: 'call', label: '喊话'},
      {value: 'draw', label: '拉弓'}, {value: 'first', label: '第一箭'}, {value: 'volley', label: '一箭接一箭'}, {value: 'last', label: '留下一个'}]},
    name: {label: '名字', type: 'text', default: '后羿', maxLength: 12},
    nameSeal: {label: '名字朱印', type: 'text', default: '神箭手', maxLength: 6, help: '留空不落印'},
    nameCue: {label: '名字卡点词', type: 'text', default: '后羿', maxLength: 24},
    bowCue: {label: '神弓卡点词', type: 'text', default: '红色的神弓', maxLength: 24, help: '念到这个词，金光沿着弓走一遍'},
    arrowsCue: {label: '神箭卡点词', type: 'text', default: '白色的神箭', maxLength: 24},
    callCue: {label: '喊话卡点词', type: 'text', default: '快回家', maxLength: 24},
    playCue: {label: '玩疯卡点词', type: 'text', default: '玩疯了', maxLength: 24},
    drawCue: {label: '拉弓卡点词', type: 'text', default: '拉开', maxLength: 24},
    fullCue: {label: '拉满卡点词', type: 'text', default: '满满', maxLength: 24},
    moonCue: {label: '圆月卡点词', type: 'text', default: '月亮', maxLength: 24},
    whoosh: {label: '箭声字', type: 'text', default: '嗖', maxLength: 10},
    whooshCue: {label: '射出卡点词', type: 'text', default: '嗖', maxLength: 24},
    hit: {label: '命中字', type: 'text', default: '中', maxLength: 8},
    hitCue: {label: '命中卡点词', type: 'text', default: '正中', maxLength: 24},
    counts: {label: '倒数卡点词', type: 'list', min: 8, max: 8, maxLength: 24, default: ['八个', '七个', '六个', '五个', '四个', '三个', '两个', '一个'],
      help: '一箭接一箭：念到第几个词就射中第几个太阳'},
    nockCue: {label: '搭箭卡点词', type: 'text', default: '搭上', maxLength: 24},
    peopleCue: {label: '人们卡点词', type: 'text', default: '人们', maxLength: 24, help: '留下一个：念到这个词，切到村民'},
    lowerCue: {label: '放下弓卡点词', type: 'text', default: '笑了笑', maxLength: 24, help: '留下一个：念到这个词，切到后羿放下神弓'},
    counterLabel: {label: '计数说明', type: 'text', default: '天上的太阳', maxLength: 16},
    numerals: {label: '计数字', type: 'list', min: 11, max: 11, maxLength: 4, default: ['', '一', '二', '三', '四', '五', '六', '七', '八', '九', '十'], help: '0 到 10 的写法'},
  },
  slots: {'houyi-hero': '后羿登场', 'houyi-call': '后羿喊话', 'houyi-draw': '拉满神弓', 'sky-shoot': '山顶射日远景', villagers: '村民劝阻', 'houyi-smile': '后羿放下神弓'},
};
const HERO_SUNS = [[1000, 140], [1180, 90], [1360, 170], [1540, 100], [1720, 180], [1080, 330], [1270, 300], [1460, 330], [1650, 360], [1840, 290]];
const BOW = [[90, 435], [210, 600], [315, 652], [435, 697], [630, 735], [765, 765]];
const SHOOT = [[900, 190], [1110, 120], [1330, 210], [1550, 110], [1760, 200], [980, 380], [1200, 330], [1430, 400], [1660, 350], [1850, 470]];
const ORDER = [5, 0, 7, 3, 9, 1, 6, 8, 4];
const LAST = 2, TIP = [495, 515], SEA = 958;

const along = (pts: number[][], u: number) => {
  const segs = pts.slice(1).map((p, i) => Math.hypot(p[0] - pts[i][0], p[1] - pts[i][1])), total = segs.reduce((a, b) => a + b, 0);
  let d = clamp(u) * total, i = 0;
  while (i < segs.length - 1 && d > segs[i]) {d -= segs[i]; i++;}
  const k = segs[i] ? d / segs[i] : 0;
  return [mix(pts[i][0], pts[i + 1][0], k), mix(pts[i][1], pts[i + 1][1], k)];
};
/** Golden glint running along a polyline from `at` for `len` seconds. */
function Glint({pts, t, at, len = .9}: {pts: number[][]; t: number; at: number; len?: number}) {
  const u = (t - at) / len;
  if (u < 0 || u > 1.3) return null;
  const [x, y] = along(pts, u), op = u > 1 ? 1 - (u - 1) / .3 : 1;
  return <g opacity={op}>
    <polyline points={pts.map(p => p.join(',')).join(' ')} fill="none" stroke="#ffe27a" strokeWidth={10} strokeLinecap="round" strokeLinejoin="round"
      pathLength={1} strokeDasharray={`${clamp(u)} 1`} opacity={.55} />
    <polyline points={pts.map(p => p.join(',')).join(' ')} fill="none" stroke="#ffd45c" strokeWidth={26} strokeLinecap="round" strokeLinejoin="round"
      pathLength={1} strokeDasharray={`${clamp(u)} 1`} opacity={.2} />
    <circle cx={x} cy={y} r={34} fill="url(#flash)" />
    <Twinkle x={x} y={y} s={1.3} />
  </g>;
}

/** Shot schedule: hit times, launches and targets for the first/volley scenes (shared so feathers persist inside a scene). */
function shots(hits: number[], firstIndex: number) {
  return hits.map((hit, k) => ({hit, from: hit - .34, target: ORDER[firstIndex + k]}));
}

export default function Houyi(props: SceneInput) {
  const {t, at, start, end, endAll, dur} = cues(props);
  const m = mode(props, 'hero');
  const numerals = list<string>(props, 'numerals').map(String), label = txt(props, 'counterLabel');

  if (m === 'hero' || m === 'call') {
    const hero = m === 'hero';
    const named = at(txt(props, 'nameCue'), start(0, .2) + .8), bow = at(txt(props, 'bowCue'), start(1, dur * .45) + 1.2), arrows = at(txt(props, 'arrowsCue'), bow + 1.4);
    const call = at(txt(props, 'callCue'), start(1, dur * .35)), play = at(txt(props, 'playCue'), start(2, dur * .6) + .5);
    const speed = hero ? 1 : 1 + 1.6 * sm((t - play) / .8);
    const name = txt(props, 'name');
    return <div style={{position: 'absolute', inset: 0, background: INK, overflow: 'hidden', opacity: fadeEdges(t, dur)}}>
      <Plate asset={slot(props, hero ? 'houyi-hero' : 'houyi-call')} frame={props.frame} p={t / dur} from={hero ? [1.02, 0, 0] : [1.03, 0, 0]} to={hero ? [1.1, 40, 20] : [1.08, 30, 10]} origin="25% 45%">
        <Svg><Defs />
          {hero && <><Glint pts={BOW} t={t} at={bow} len={1.0} />
            {[[300, 290], [345, 255], [270, 330], [330, 320]].map(([x, y], i) => <Twinkle key={i} x={x} y={y} s={.9 + .3 * i % 2} opacity={win(t, arrows + i * .1, arrows + 1.4 + i * .1, .12)} />)}
            <circle cx={320} cy={290} r={90} fill="url(#flash)" opacity={win(t, arrows, arrows + .8, .1) * .6} /></>}
          {!hero && [0, 1, 2, 3].map(i => {const k = ((t - call) * 1.3 - i * .25); if (k < 0 || k > 1.6) return null; const q = clamp(k / 1.6);
            return <path key={i} d={`M ${780 + q * 520} ${330 - 90 - q * 120} Q ${830 + q * 600} ${360} ${780 + q * 520} ${400 + 90 + q * 120}`} fill="none" stroke="#fff6e0" strokeWidth={9 * (1 - q)} strokeLinecap="round" opacity={(1 - q) * .9} />;})}
          {HERO_SUNS.map(([x, y], i) => {
            const a = t * speed * (hero ? 1.1 : 1.6) + i * 1.3, rad = hero ? 18 : 40 + 30 * (i % 3);
            const px = hero ? x + Math.sin(a) * rad : x + 60 + Math.sin(a) * rad * 1.4, py = hero ? y + Math.cos(a * 1.3) * rad * .6 : y + 60 + Math.cos(a * 1.2) * rad;
            return <SunBird key={i} x={px} y={py} r={hero ? 40 : 44} t={t} phase={i * .37} mood={!hero && t > play ? 'joy' : 'happy'} tilt={hero ? 0 : Math.sin(a) * 25} glow={.85} />;
          })}
          {!hero && [0, 1, 2, 3, 4].map(i => {const k = ((t - play) * .7 + i * .2) % 1; if (t < play) return null;
            return <path key={`n${i}`} transform={`translate(${1150 + i * 150} ${560 - k * 260}) scale(1.4)`} opacity={Math.sin(Math.PI * k) * .9} fill="#fff6e0"
              d="M 0 0 a 7 5 -20 1 0 0.1 0 Z M 6 -1 L 6 -30 L 18 -26 L 18 -20 L 8 -23 L 8 -1 Z" />;})}
        </Svg>
      </Plate>
      {hero && <Svg><Defs />
        <Brush id="hn" text={name} x={isLatin(name) ? 1340 : 1120} y={560} size={230} p={clamp((t - named) / .55)} fill={PAPER} stroke="#7a2a0e" maxWidth={720} align={isLatin(name) ? 'middle' : 'start'} />
        <Seal id="hs" text={txt(props, 'nameSeal')} x={isLatin(name) ? 1340 : 1120 + Array.from(name).length * 230 * .96 + 70} y={isLatin(name) ? 880 : 700} size={100} p={clamp((t - named - .5) / .3)} />
      </Svg>}
      <Finish vignette={.35} />
    </div>;
  }

  if (m === 'draw') {
    const drawAt = at(txt(props, 'drawCue'), start(0, .2) + .6), full = at(txt(props, 'fullCue'), start(1, dur * .45) + .4), moon = at(txt(props, 'moonCue'), end(1, dur) - 1.0);
    const tension = sm((t - drawAt) / Math.max(.5, full - drawAt + .6));
    const zoom = 1.0 + .16 * tension, vig = .3 + .45 * tension;
    const tremble = t > full ? Math.sin(t * 47) * 1.6 * tension : 0;
    const ring = clamp((t - moon + .1) / .8);
    return <div style={{position: 'absolute', inset: 0, background: INK, overflow: 'hidden', opacity: fadeEdges(t, dur, .1, .06)}}>
      <Plate asset={slot(props, 'houyi-draw')} frame={props.frame} p={tension} from={[1.0, 0, 0]} to={[zoom, -30, 10]} origin="42% 45%" shift={[tremble, tremble * .6]}>
        <Svg><Defs />
          {Array.from({length: 9}, (_, i) => {const k = (t * (.9 + .5 * tension) + i * .37) % 1, y = 80 + i * 115;
            return <path key={i} d={`M ${W + 100 - k * 2600} ${y} q 120 -14 260 0`} stroke="#fff6e0" strokeWidth={4} fill="none" strokeLinecap="round" opacity={(.15 + .3 * tension) * Math.sin(Math.PI * k)} />;})}
          <polyline points="1040,0 452,540 1050,1080" fill="none" stroke="#fff3b0" strokeWidth={5} opacity={sm((t - full) / .4) * (.45 + .25 * Math.sin(t * 20))} />
          <polyline points="1040,0 452,540 1050,1080" fill="none" stroke="#ffd45c" strokeWidth={16} opacity={sm((t - full) / .4) * .18} />
          <circle cx={1372} cy={277} r={50} fill="url(#flash)" opacity={sm((t - full) / .4) * (.6 + .3 * Math.sin(t * 9))} />
          <circle cx={830} cy={540} r={515} fill="none" stroke="#ffe27a" strokeWidth={14} pathLength={1} strokeDasharray={`${ring} 1`} transform="rotate(-90 830 540)"
            opacity={ring > 0 ? .85 : 0} />
          <circle cx={830} cy={540} r={515} fill="none" stroke="#ffd45c" strokeWidth={40} pathLength={1} strokeDasharray={`${ring} 1`} transform="rotate(-90 830 540)" opacity={ring > 0 ? .2 : 0} />
          <circle cx={830} cy={540} r={515} fill="rgba(255,244,200,.12)" opacity={sm((t - moon - .5) / .5)} />
        </Svg>
      </Plate>
      <Finish vignette={vig} />
    </div>;
  }

  // first / volley / last share the mountain-top sky.
  const counts = list<string>(props, 'counts').map(String).slice(0, 8);
  let schedule: {hit: number; from: number; target: number}[] = [], before = 10;
  if (m === 'first') {
    const whoosh = at(txt(props, 'whooshCue'), start(0, .2) + .5), hit = Math.max(whoosh + .55, at(txt(props, 'hitCue'), whoosh + 1.6));
    schedule = [{hit, from: Math.min(whoosh, hit - .5), target: ORDER[0]}];
  } else if (m === 'volley') {
    before = 9;
    const s1 = start(1, dur * .45);
    schedule = shots(counts.map((word, i) => at(word, s1 + .1 + i * .62) + .02), 1);
  } else before = 1;
  const done = schedule.filter(s => t >= s.hit).length, count = before - done, changedAt = done ? schedule[done - 1].hit : -9;
  const alive = (i: number) => m === 'last' ? i === LAST : !ORDER.slice(0, 10 - before).includes(i) && !schedule.some(s => s.target === i && t >= s.hit);
  const lastShake = schedule.reduce((acc, s) => t >= s.hit ? shake(t, s.hit, m === 'first' ? 10 : 6, .35) || acc : acc, '');

  if (m === 'last') {
    const nock = at(txt(props, 'nockCue'), start(1, dur * .25) + .6), people = at(txt(props, 'peopleCue'), start(1, dur * .25) + 1.6) - .15;
    const lower = at(txt(props, 'lowerCue'), start(4, dur * .8)) - .3, plead1 = start(2, people + 1.4), plead2 = start(3, plead1 + 1.2);
    const scene = t < start(1, dur * .25) - .05 ? 'zoom' : t < people ? 'wide' : t < lower ? 'people' : 'smile';
    const zk = sm(t / Math.max(.8, start(1, dur * .25)));
    const [lx, ly] = SHOOT[LAST];
    return <div style={{position: 'absolute', inset: 0, background: INK, overflow: 'hidden', opacity: fadeEdges(t, dur, .08, .12)}}>
      {(scene === 'zoom' || scene === 'wide') && <Plate asset={slot(props, 'sky-shoot')} frame={props.frame} p={scene === 'zoom' ? zk : 0} from={[1.02, 0, 0]} to={scene === 'zoom' ? [1.85, 0, 0] : [1.02, 0, 0]} origin={`${lx / W * 100}% ${ly / H * 100}%`}>
        <Svg><Defs />
          <SunBird x={lx + Math.sin(t * 23) * 3} y={ly + Math.sin(t * 1.5) * 6} r={50} t={t} phase={.2} mood="worried" tilt={Math.sin(t * 17) * 4} flap={1.6} />
          {scene === 'wide' && <><circle cx={TIP[0]} cy={TIP[1]} r={46} fill="url(#flash)" opacity={win(t, nock, people, .15) * (.7 + .3 * Math.sin(t * 10))} />
            <Twinkle x={TIP[0]} y={TIP[1]} s={1.2} opacity={win(t, nock, people, .15)} /></>}
        </Svg>
      </Plate>}
      {scene === 'people' && <Plate asset={slot(props, 'villagers')} frame={props.frame} p={(t - people) / Math.max(1, lower - people)} from={[1.03, 0, 0]} to={[1.1, 0, -20]} origin="50% 40%">
        <Svg>{[[plead1, 395, 300], [plead2, 640, 270]].map(([s, x, y], j) => [0, 1, 2].map(i => {
          const a = -1.9 + i * .45, k = sm((t - s) / .25) * (1 - sm((t - s - 1.2) / .3)), l0 = 70, l1 = 70 + 40 * k;
          return <line key={`${j}-${i}`} x1={x + Math.cos(a) * l0} y1={y + Math.sin(a) * l0} x2={x + Math.cos(a) * l1} y2={y + Math.sin(a) * l1} stroke="#8a3a12" strokeWidth={7} strokeLinecap="round" opacity={k} />;
        }))}</Svg>
      </Plate>}
      {scene === 'smile' && <Plate asset={slot(props, 'houyi-smile')} frame={props.frame} p={(t - lower) / Math.max(1, dur - lower)} from={[1.02, 0, 0]} to={[1.07, 20, 0]} origin="30% 40%">
        <Svg><Defs />
          <SunBird x={1380} y={250 + Math.sin(t * 1.6) * 8} r={72} t={t} phase={.2} mood="joy" />
          {[0, 1, 2, 3].map(i => <Twinkle key={i} x={1300 + (i % 2) * 170} y={150 + Math.floor(i / 2) * 210} s={.8} opacity={win(t, lower + .5 + i * .12, dur + 1, .2) * (.5 + .5 * Math.sin(t * 5 + i))} />)}
        </Svg>
      </Plate>}
      {scene !== 'people' && scene !== 'smile' && <Svg><Defs /><SunCounter count={1} t={t} label={label} numerals={numerals} /></Svg>}
      <Finish vignette={.35} />
    </div>;
  }

  const first = m === 'first';
  const hit0 = schedule[0]?.hit ?? 1;
  const whooshText = txt(props, 'whoosh'), hitText = txt(props, 'hit');
  const tgt = SHOOT[schedule[0]?.target ?? 0];
  const nervous = first ? 0 : sm((t - .3) / 1);
  return <div style={{position: 'absolute', inset: 0, background: INK, overflow: 'hidden', opacity: fadeEdges(t, dur, .06, .1)}}>
    <div style={{position: 'absolute', inset: 0, transform: lastShake}}>
      <Plate asset={slot(props, 'sky-shoot')} frame={props.frame} p={t / dur} from={first ? [1.04, 0, 0] : [1.08, 0, -20]} to={first ? [1.08, 0, -40] : [1.02, 0, 0]} origin="40% 60%">
        <Svg><Defs />
          {SHOOT.map(([x, y], i) => alive(i) ? <SunBird key={i} x={x + Math.sin(t * (2 + 6 * nervous) + i) * (6 + 10 * nervous)} y={y + Math.cos(t * (1.6 + 5 * nervous) + i) * (5 + 8 * nervous)} r={44} t={t}
            phase={i * .37} mood={!first || t > hit0 ? 'worried' : 'happy'} flap={1 + nervous} glow={.85} /> : null)}
          {schedule.map((s, k) => <Arrow key={`a${k}`} t={t} from={s.from} hit={s.hit} x0={TIP[0]} y0={TIP[1]} x1={SHOOT[s.target][0]} y1={SHOOT[s.target][1]} lift={first ? 160 : 110} />)}
          {schedule.map((s, k) => <HitFlash key={`h${k}`} t={t} at={s.hit} x={SHOOT[s.target][0]} y={SHOOT[s.target][1]} r={first ? 80 : 60} />)}
          {schedule.map((s, k) => <FeatherBurst key={`f${k}`} t={t} at={s.hit} x={SHOOT[s.target][0]} y={SHOOT[s.target][1]} floor={SEA} seed={s.target + 1} n={first ? 18 : 11} fall={first ? 3.4 : 2.6} scale={first ? 1.25 : 1} />)}
          {schedule.map((s, k) => <Ripples key={`r${k}`} t={t} at={s.hit} x={SHOOT[s.target][0]} floor={SEA} seed={s.target + 1} fall={first ? 3.4 : 2.6} n={first ? 7 : 4} />)}
          {first && <Brush id="wh" shadow={false} text={whooshText} x={(TIP[0] + tgt[0]) / 2 - 150} y={300} size={150} p={clamp((t - schedule[0].from) / .25) * (1 - sm((t - hit0 - .5) / .4))} fill={PAPER} stroke="#7a2a0e" />}
          {first && t >= hit0 && <g transform={`translate(${tgt[0] + 70} ${tgt[1] - 250}) scale(${outBack((t - hit0) / .35)})`} opacity={1 - sm((t - hit0 - 1.6) / .4)}>
            <Brush id="hz" shadow={false} text={hitText} x={0} y={0} size={190} fill={RED} stroke={PAPER} />
            <path d="M 205 30 L 225 30 L 219 130 L 211 130 Z M 215 150 m -12 0 a 12 12 0 1 0 24 0 a 12 12 0 1 0 -24 0" fill={RED} stroke={PAPER} strokeWidth={4} />
          </g>}
        </Svg>
      </Plate>
    </div>
    <Svg><Defs /><SunCounter count={count} t={t} changedAt={changedAt} label={label} numerals={numerals} /></Svg>
    {schedule.map((s, k) => t >= s.hit && t < s.hit + .1 ? <div key={k} style={{position: 'absolute', inset: 0, background: `rgba(255,250,220,${(first ? .5 : .3) * (1 - (t - s.hit) / .1)})`}} /> : null)}
    <Finish vignette={.32} />
  </div>;
}
